from unittest.mock import patch

class FirstFormatter:
    def __init__(self, env, **kwargs):
        self.enabled = True

    def format_headers(self, headers):
        return f"{headers} -> first"

class DisabledFormatter:
    def __init__(self, env, **kwargs):
        self.enabled = False

    def format_headers(self, headers):
        raise AssertionError("Disabled formatter should not be invoked")

class SecondFormatter:
    def __init__(self, env, **kwargs):
        self.enabled = True

    def format_headers(self, headers):
        return f"{headers} -> second"

available_plugins = {
    "test": [FirstFormatter, DisabledFormatter, SecondFormatter],
}

with patch.object(
    plugin_manager,
    "get_formatters_grouped",
    return_value=available_plugins,
):
    formatting = Formatting(groups=["test"])
    result = formatting.format_headers("Content-Type: application/json")

assert result == (
    "Content-Type: application/json -> first -> second"
)

